func (rs *Resource) Router() chi.Router {
	r := chi.NewRouter()
	r.Use(render.SetContentType(render.ContentTypeJSON))
	rs.runtime.Protected(r, func(r chi.Router, withTx Middleware) {
		r.Use(rs.runtime.RequireWrite)
		r.With(withTx).Get("/", rs.status)
		r.With(withTx).Put("/steps/{step}", rs.skipStep)
		r.With(withTx).Post("/complete", rs.complete)
		r.With(withTx).Put("/dismissal", rs.dismiss)
	})
	return r
}

func (rs *StaffResource) Router() chi.Router {
	r := chi.NewRouter()
	r.Use(render.SetContentType(render.ContentTypeJSON))
	rs.runtime.Protected(r, func(r chi.Router, withTx Middleware) {
		r.With(withTx).Get("/", rs.status)
		r.With(withTx).Put("/steps/{step}", rs.setStepState)
		r.With(withTx).Put("/dismissal", rs.dismiss)
	})
	return r
}

func (p progress[Flags]) Facts(ctx context.Context, tenantID int64) (schoolsetup.Facts, error) {
	row, err := p.source.Progress(ctx, tenantID)
	if err != nil {
		return schoolsetup.Facts{}, err
	}
	staff, room, group, student, guardian := row.ProgressFlags()
	return schoolsetup.Facts{StaffInvited: staff, RoomCreated: room, GroupCreated: group, StudentEnrolled: student, GuardianInvited: guardian}, nil
}
